import 'package:firebase_core/firebase_core.dart';

import '../app/flavor.dart';
import 'options_driver.dart' as driver;
import 'options_rider.dart' as rider;

/// Firebase settings per app, generated by FlutterFire into options_rider.dart and
/// options_driver.dart (one Firebase Android app each: com.konduct.rider, com.konduct.driver).
/// Until those are generated they return null and the app runs in demo mode.
///
/// `--dart-define=KONDUCT_DEMO=true` forces demo mode even when configured.
const _forceDemo = bool.fromEnvironment('KONDUCT_DEMO');

FirebaseOptions? firebaseOptionsFor(Flavor f) {
  if (_forceDemo) return null;
  return f.isRider ? rider.DefaultFirebaseOptions.currentPlatform : driver.DefaultFirebaseOptions.currentPlatform;
}
